{
  "packet_id": "H6-T02-3",
  "claim_id": "C013",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C013.component",
    "value": "With adequate telemetry, the proposed perturbation is a single documented decrease from baseline concurrency c0 to a lower canary concurrency c1, held constant after the change.",
    "scope": "Conditional experimental design, not an assertion that telemetry is adequate or the step has occurred.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P009 supplies the telemetry condition, baseline, documented single decrease, canary scope, and constant subsequent setting."
    }
  },
  "signal_basis": {
    "component_id": "C013.signal_basis",
    "value": "The prescribed operation records a baseline at c0, then applies one known decrease to c1 at a documented time and holds that setting constant. Actual concurrency is tracked as active exports finish.",
    "scope": "Proposed canary operation with adequate telemetry; holding the setting constant does not assert that actual concurrency changes instantaneously.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P036",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The spans establish the controlled step and distinguish the commanded setting from its potentially gradual realization."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C013.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This operational design claim requires no unresolved empirical relation."
    }
  },
  "rationale": "The claim faithfully describes the prescribed operation within its explicit telemetry condition and experimental scope. It asserts neither completed execution nor a performance consequence.",
  "uncertainty": "No material uncertainty about this design claim; gradual realization of the concurrency limit does not contradict the prescribed constant setting.",
  "anomalies": []
}
